28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const PROCESSING_FEE = 5;
38	
39	const WHOLE_PERCENT = 100;
40	
41	/**
42	 * Surcharges multiply before dividing, so the arithmetic stays exact.
43	 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
44	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
45	 * instead of 115 G.
46	 */
47	const addSurcharge = (amount: number, surchargePercent: number): number =>
48	  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;
49	
50	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
51	
52	/** All rounding is in the MHPCO's favor — always up. */
53	const roundInMHPCOsFavor = Math.ceil;
54	
55	const BUILDING_BLOCK_SIZE = 3;
56	const BUILDING_BLOCK_PREMIUM = 60;
57	
58	const areAllSameType = ([first, ...rest]: InsuredItem[]): boolean =>
59	  rest.every((item) => item.type === first?.type);
60	
61	const sumIndividually = (items: InsuredItem[]): number =>
62	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
63	
64	/**
65	 * Prices an item list by whichever rule applies: alike items are grouped into
66	 * building blocks sold at a flat rate, and whatever is left over — plus any
67	 * mixed list — is the sum of its items' base premiums.
68	 */
69	const priceItems = (items: InsuredItem[]): number => {
70	  if (!areAllSameType(items)) return sumIndividually(items);
71	
72	  const blocks = Math.floor(items.length / BUILDING_BLOCK_SIZE);
73	  const loose = items.slice(blocks * BUILDING_BLOCK_SIZE);
74	
75	  return blocks * BUILDING_BLOCK_PREMIUM + sumIndividually(loose);
76	};
77	
78	/**
79	 * The premium pipeline, in the order the spec states it: price the items,
80	 * apply surcharges, round, then add the processing fee last.
81	 */
82	const quotePremium = (step: Step): QuoteResult => {
83	  const basePremium = priceItems(step.items ?? []);
84	  const surcharged = addSurcharge(
85	    basePremium,
86	    FIRST_INSURANCE_SURCHARGE_PERCENT,
87	  );
88	
89	  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
90	};
91	
92	export const runScenario = (scenario: Scenario): ScenarioResults => ({
93	  results: scenario.steps.map(quotePremium),
94	});
