/**
 * How many flat-rate blocks this list forms. A mixed list forms none — only
 * alike items group — and so does any list too short to fill one block.
 */
const completeBlocks = ([first, ...rest]: InsuredItem[]): number => {
  const alike = rest.every((item) => item.type === first?.type);

  return alike ? Math.floor((rest.length + 1) / BUILDING_BLOCK_SIZE) : 0;
};

